import{_ as n,C as i,o as r,c as h,a5 as o,E as a,j as s,a as d}from"./chunks/framework.DtspaGiy.js";const p="/dev/screenshots/header-footer.gif",l="/dev/screenshots/even-pages.gif",b=JSON.parse('{"title":"Pages","description":"","frontmatter":{},"headers":[],"relativePath":"guide/pages.md","filePath":"guide/pages.md"}'),c={name:"guide/pages.md"};function g(u,e,m,k,f,w){const t=i("Shot");return r(),h("div",null,[e[0]||(e[0]=o('<h1 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h1><p>Your PDF and Word documents come out on the paper of your region, A4 or Letter, with generous margins of 2.5 cm. Most documents never need more than that. When one does, the <a href="#page-setup">page setup</a> is a click or a shortcut away.</p><h2 id="on-the-screen" tabindex="-1">Your pages on the screen <a class="header-anchor" href="#on-the-screen" aria-label="Permalink to &quot;Your pages on the screen {#on-the-screen}&quot;">​</a></h2><p>Blank shows your text the way it prints: every line and every page ends on the screen exactly where it ends in the PDF. (A Word document is laid out by Word, so its lines can end elsewhere.) There are two ways to look at it, and <code>Mod</code> <code>Alt</code> <code>V</code> switches between them, keeping your place:</p><ul><li><strong>Page ends</strong> (where Blank starts): one calm column of text, as wide as it is on the paper. Where one page ends and the next begins, a dashed line shows the page&#39;s number and footer, and the header of the page that follows. The first page&#39;s header sits above your text, and the last page&#39;s footer below it. A new document is just that: an empty page and your caret.</li><li><strong>Pages</strong>: the sheets themselves, one below the other, with their margins, headers, footers and page numbers in place.</li></ul>',5)),a(t,{src:"page-views.gif",alt:"Mod Alt V switches from Page ends, one column with a dashed line where each page ends, to Pages, the sheets on a desk, and back"}),e[1]||(e[1]=o('<p>Blank remembers your choice. The button at the right end of the bar at the bottom switches between the two views too: its icon shows the view you&#39;re in. Next to it, the bar tells you which page you&#39;re looking at, like <em>Page 3 of 12</em>, and counts along as you scroll; click it to jump to another page, listed with the first heading on each. <code>Page Up</code> and <code>Page Down</code> move a screen at a time, and dragging past the top or bottom of the window scrolls along.</p><h2 id="zoom" tabindex="-1">Zoom <a class="header-anchor" href="#zoom" aria-label="Permalink to &quot;Zoom {#zoom}&quot;">​</a></h2><p>At first, Blank fits your pages to the window: as wide as it allows, at most the size they print at (in page ends, the size of your text in the editor, a little larger). To see them larger or smaller, press <code>Mod</code> <code>=</code> (or <code>Mod</code> <code>+</code>) and <code>Mod</code> <code>-</code>, or hold <code>Ctrl</code> and turn the mouse wheel. The zoom goes in steps from 50% to 200%, where 100% is the size the pages print at, in both views. The spot under the pointer stays where it is while you zoom with the wheel, and with the keys, your cursor does.</p><p>The bar at the bottom shows the zoom next to the view button, between − and +. A click on it fits the pages to the window again; with <em>Fit</em>, its tooltip says the size that gives, like <em>Fit to window (87%)</em>. A page wider than the window scrolls sideways. Blank remembers the zoom for the next time you open it.</p><p>Only the pages zoom: the bars, menus and dialogs keep their size.</p>',5)),a(t,{src:"zoom.gif",alt:"The + in the bar at the bottom zooms the pages in twice and − out once; a click on the zoom fits them to the window again; Mod = and Mod - zoom in and out"}),e[2]||(e[2]=s("h2",{id:"outline",tabindex:"-1"},[d("Find your way with the outline "),s("a",{class:"header-anchor",href:"#outline","aria-label":'Permalink to "Find your way with the outline {#outline}"'},"​")],-1)),e[3]||(e[3]=s("p",null,"Once your document has two headings, a short dash for each of them sits at the right edge of the window, longer for a heading 1 and shorter for the levels below. The dash of the section you're reading is in your accent color.",-1)),e[4]||(e[4]=s("p",null,"Point at the dashes to see all your headings, and click one to scroll straight to it. In the list, a short line in your accent color marks where you are. Your cursor stays where you were writing, so you can look something up and keep typing right away.",-1)),a(t,{src:"outline.gif",alt:"Pointing at the dashes on the right shows the headings of the document; a click on one scrolls to it, and Mod Alt O opens and closes the list"}),e[5]||(e[5]=o('<p>To keep the outline open, click the dashes or press <code>Mod</code> <code>Alt</code> <code>O</code>. On a window at least 1000 pixels wide, the list stays beside your pages, and they move over a little if they need the room. On a smaller window it floats over the pages until you click a heading or somewhere else. <code>Mod</code> <code>Alt</code> <code>O</code> or the × at the top of the list puts it away again, and Blank remembers whether you keep it open. Rest the pointer on the dashes or the × to see the shortcut.</p><h2 id="page-setup" tabindex="-1">Page setup <a class="header-anchor" href="#page-setup" aria-label="Permalink to &quot;Page setup {#page-setup}&quot;">​</a></h2><p>Click the paper in the bar at the bottom (e.g. <em>A4</em>), press <code>Mod</code> <code>Alt</code> <code>U</code>, or choose <strong>Page setup…</strong> from the menu (right-click or <code>Shift</code> <code>F10</code>).</p>',3)),a(t,{src:"page-setup.png",alt:"The page setup dialog with the paper, orientation, margins and the headings that start a new page, and a picture of the page beside them"}),e[6]||(e[6]=o('<table tabindex="0"><thead><tr><th>Setting</th><th>Choices</th></tr></thead><tbody><tr><td>Paper</td><td>the paper of your region, A3, A4, A5, B5, Letter, Legal, or any size</td></tr><tr><td>Orientation</td><td>portrait or landscape</td></tr><tr><td>Margins</td><td>narrow (1.27 cm), normal (2.5 cm), wide (3.5 cm), or your own</td></tr><tr><td>New page before</td><td>H1 to H6: the <a href="#chapters">headings that start a new page</a></td></tr></tbody></table><p>Pick the paper from its list, and click the orientation and margins you want. The picture beside them follows every change, so you see your page before you apply it, and <strong>Apply</strong> puts it on your document.</p><p>For a size or margins of your own, choose <strong>Custom…</strong> and type them in the fields that open below. The paper is in millimeters, or in inches where Letter paper is used, and the margins in centimeters or inches. You can also write the unit, like <code>25mm</code> or <code>1in</code>. Type a width larger than the height, and the page turns to landscape by itself. If something can&#39;t work, say margins that leave no room for your text, the dialog tells you right below and waits until it&#39;s fixed.</p><p><strong>Make this my default</strong> keeps the setup for <a href="#defaults">new documents and every document without its own</a>.</p><p>Changed your mind? <code>Mod</code> <code>Z</code> undoes the whole page setup at once.</p><p>It all works from the keyboard too:</p><ul><li><code>↑</code> <code>↓</code> move between the settings and fields.</li><li><code>←</code> <code>→</code> change a setting, also the paper. <code>Home</code> and <code>End</code> jump to a setting&#39;s first or last choice.</li><li><code>Space</code> turns a heading on or off. On the paper, <code>Space</code>, <code>Enter</code> or <code>Alt</code> <code>↓</code> open its list.</li><li><code>Enter</code> applies, and <code>Esc</code> leaves everything as it was.</li></ul><h2 id="headers-and-footers" tabindex="-1">Page numbers, headers and footers <a class="header-anchor" href="#headers-and-footers" aria-label="Permalink to &quot;Page numbers, headers and footers {#headers-and-footers}&quot;">​</a></h2><p>Point at the bottom margin of a page, or just below the last page, and click <strong>+ Footer</strong>. The footer opens right where it prints: three places in the margin, on the left, in the center and on the right, and a strip beside them. Everything else steps back while you edit. Click <strong>Page number</strong>, pick how it reads, and click <strong>Done</strong>: every page of your PDF and Word document now has its number at the bottom. A header works the same from the top margin with <strong>+ Header</strong>.</p><p>The fast way is the keyboard: <code>Mod</code> <code>Alt</code> <code>F</code> opens the footer and <code>Mod</code> <code>Alt</code> <code>H</code> the header, on the page you&#39;re looking at.</p><p>Click a place and type, or put something in with the strip&#39;s buttons:</p><ul><li><strong>Page number</strong> puts in the number of the page. Its menu offers <em>1</em>, <em>Page 1</em>, <em>1 of 2</em> and <em>Page 1 of 2</em>, numbers in the style <em>1, 2, 3</em>, <em>i, ii, iii</em> or <em>I, II, III</em>, and <strong>Start at…</strong> for the number of the first page, e.g. 0 to leave a title page uncounted.</li><li><strong>Title</strong> and <strong>Author</strong> put in the document&#39;s title and author, which follow the <a href="./files#frontmatter">properties</a>. Without a title, the first heading is the title.</li><li><strong>Chapter</strong> puts in the chapter a page belongs to: the first heading 1 on the page, or else the last one before it. A running head, as in books.</li><li><strong>Date</strong> puts in the date of the export, and <strong>File</strong> the name of the file.</li></ul><p>In a place, they show by their name, like <strong>Page</strong> or <strong>Title</strong>, and your pages show what they stand for. <strong>Remove</strong> clears the header or footer from every page.</p><img class="shot" src="'+p+'" alt="Pointing below the page shows + Footer; a click opens the footer, where Page number puts the number in the center. Mod Alt H opens the header, where Chapter goes on the left, Page 1 of 2 on the right, and First page None leaves the title page plain"><p><code>Tab</code> moves to the next place and on to the strip&#39;s buttons. <code>Enter</code>, <code>Esc</code> or a click anywhere in your text is done. Your pages show what they carry: in <strong>Pages</strong> on every sheet, and in <strong>Page ends</strong> above the first page, between the pages and below the last one. Click a header or footer there to change it; on a sheet, anywhere in its top or bottom margin does. <code>Mod</code> <code>Z</code> in your text undoes the whole change.</p><p>When a placeholder has nothing to put in yet, say <strong>Author</strong> while the document has no author, or <strong>Chapter</strong> before the first heading 1, your pages show its name there in faint italics, so you can still see the header or footer and click it. Only the screen shows these names: your PDF and Word document leave the place empty until there is something to put in. And if the header or footer you&#39;re done with shows nothing at all on your page yet, the bottom bar tells you why, say that no author is set, and how to set one.</p><h3 id="first-and-even-pages" tabindex="-1">The first page and even pages <a class="header-anchor" href="#first-and-even-pages" aria-label="Permalink to &quot;The first page and even pages {#first-and-even-pages}&quot;">​</a></h3><p>In the strip, <strong>First page</strong> chooses what the first page has: <strong>The same as the others</strong>, <strong>None</strong>, e.g. for a title page, or <strong>Its own</strong>, e.g. a letterhead with your address on the first page and just the page number after it.</p><p>Switch on <strong>Odd and even pages differ</strong> to give the left and right pages of a book their own header and footer. Odd and even pages then have two headers and two footers, each kept on its own. The even pages start as the odd ones mirrored, so the page numbers sit on the outside. Changed the odd pages later? <strong>Mirror the odd pages</strong> copies them to the even pages again, left and right swapped. As in Word, a page counts as even by the number it shows.</p><img class="shot" src="'+l+'" alt="Mod Alt F opens the footer, with the title in the center and the page number on the right; switching on Odd and even pages differ adds even pages, with the page number mirrored to the left, and the tabs switch between odd and even pages"><p>When the first or even pages have their own, the strip&#39;s <strong>Editing</strong> row switches between them. Opening a header or footer on a page shows the one that page has: the first page&#39;s own on the first page, the even pages&#39; on an even one.</p><h2 id="page-breaks" tabindex="-1">Page breaks <a class="header-anchor" href="#page-breaks" aria-label="Permalink to &quot;Page breaks {#page-breaks}&quot;">​</a></h2>',22)),a(t,{src:"page-break.png",alt:"A page break between two paragraphs, shown as a dashed line labelled Page break"}),e[7]||(e[7]=o(`<p>Press <code>Mod</code> <code>Enter</code> to continue on a new page, as in Word and Google Docs. You can also type <code>+++</code> on an empty line and press <code>Enter</code>. The page ends right there, and Blank labels it <em>Page break</em> (only on the screen, not on paper). To remove it, press <code>Backspace</code> at the start of the line below it.</p><p>In the file, a page break is the line <code>&lt;!-- pagebreak --&gt;</code>, which other markdown apps don&#39;t show. Blank also reads pandoc&#39;s <code>\\newpage</code>.</p><h2 id="chapters" tabindex="-1">Chapters on new pages <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters on new pages {#chapters}&quot;">​</a></h2><p>For a book, a thesis or a long report, turn on <strong>H1</strong> under <strong>New page before</strong> in the page setup: every heading 1 then starts a new page, in the PDF and in Word. Turn on more levels, e.g. <strong>H2</strong> for sections, and those start new pages too. With the keyboard, <code>←</code> <code>→</code> move between the headings and <code>Space</code> turns one on or off.</p><p>A heading right after a page break stays where it is, so you never get an empty page. In the <a href="#frontmatter">properties</a>, the setting reads <code>new-page-before: [1, 2]</code>.</p><h2 id="frontmatter" tabindex="-1">Where the page setup is kept <a class="header-anchor" href="#frontmatter" aria-label="Permalink to &quot;Where the page setup is kept {#frontmatter}&quot;">​</a></h2><p>The page setup belongs to the document, so it prints the same on every computer. Blank writes it into the <a href="./files#frontmatter">properties at the top of the file</a>, and only what differs from your defaults:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">page</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">a5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  orientation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">landscape</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  margins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2cm</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  header</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">left</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{title}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">right</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Page {page} of {pages}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  footer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">center</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{page}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  first-page</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">plain</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  even-pages</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    header</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">left</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Page {page} of {pages}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">right</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{chapter}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  number-style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span></code></pre></div><p>You can write these yourself too. <code>new-page-before</code> lists the heading levels that start a new page. <code>header</code> and <code>footer</code> have a <code>left</code>, <code>center</code> and <code>right</code> of one line each, in which <code>{page}</code> is the page number, <code>{pages}</code> the number of pages, <code>{title}</code> and <code>{author}</code> come from the properties, <code>{chapter}</code> is the chapter of the page, <code>{date}</code> the date of the export and <code>{file}</code> the name of the file; write <code>{{</code> for a brace of your own. <code>first-page</code> is <code>plain</code> for none on the first page, or its own <code>header</code> and <code>footer</code>, and <code>even-pages</code> has the <code>header</code> and <code>footer</code> of even pages, or is <code>same</code> for the same as on the other pages. <code>number-style</code> is <code>1</code>, <code>i</code> or <code>I</code>, and <code>start-number: 0</code> numbers the pages from 0, e.g. to leave the title page uncounted. <code>size</code> is <code>a3</code>, <code>a4</code>, <code>a5</code>, <code>b5</code>, <code>letter</code>, <code>legal</code>, <code>auto</code> for the paper of your region, or a size like <code>170mm x 240mm</code>. <code>margins</code> is one length for all four sides, or <code>top</code>, <code>right</code>, <code>bottom</code> and <code>left</code> on their own lines. Lengths are written with their unit: <code>mm</code>, <code>cm</code>, <code>in</code> or <code>pt</code>.</p><p>The page setup stays out of the way of your text: the bar at the bottom shows the paper, e.g. <em>A5 landscape</em>, and a click on it opens the page setup.</p><p>If a setting can&#39;t be used, say a paper size Blank doesn&#39;t know, the export uses your default for it and tells you so.</p><h2 id="defaults" tabindex="-1">Your defaults <a class="header-anchor" href="#defaults" aria-label="Permalink to &quot;Your defaults {#defaults}&quot;">​</a></h2><p><strong>Make this my default</strong> in the page setup keeps the settings for every document that doesn&#39;t have its own. Blank saves them in <a href="./configuration#page-setup"><code>blank.json</code></a>.</p><h2 id="word" tabindex="-1">Page setup and Word <a class="header-anchor" href="#word" aria-label="Permalink to &quot;Page setup and Word {#word}&quot;">​</a></h2><p>Word documents keep their page setup both ways: an export to Word has your paper, orientation, margins, page breaks, chapters on new pages, and your headers and footers with Word&#39;s own page numbers, chapter, date and file name, including those of the first and even pages. A Word document you open brings along its own, including its page breaks, section breaks, headers, footers and page numbers. If someone changed the page setup in Word, you get their version.</p><p>Word can do a few things Blank&#39;s page setup can&#39;t hold. When a document has them, Blank tells you right after opening it:</p><ul><li>sections with different page setups: Blank uses the first one,</li><li>a binding margin, which is left out,</li><li>mirrored margins for printing both sides, which become the same on every page,</li><li>pictures, tables or several lines in a header or footer, of which Blank keeps the text on one line,</li><li>page numbers in letters (a, b, c), which become 1, 2, 3.</li></ul><p>Headers and footers keep their text, not its formatting: bold, colors or another font are left out, as in the rest of the document.</p>`,18))])}const E=n(c,[["render",g]]);export{b as __pageData,E as default};
